use std::sync::Arc;

use async_trait::async_trait;
use serde_json::Value;

use crate::{
    Agent, AgentInput, HookRegistry, MemorySession, RunContext, RunError, RunResultStreaming, Tool,
    ToolContext, ToolError, ToolOutput,
