        let user_ctx = (self.ctx_factory)(seed).map_err(|e| {
            ActivityError::application(ApplicationFailure::non_retryable(format!(
                "ctx seed rejected: {e}"
            )))
        })?;
        let ctx = RunContext::ephemeral(user_ctx).with_cancel(cancel);
        Ok(self.posture.apply(ctx))
    }
